@IsTest private class SyntheticPermissionObservation {
 static User actor() {
  Profile profile = [SELECT Id FROM Profile WHERE Name='Minimum Access - Salesforce' LIMIT 1];
  return new User(Alias='synuser',Email='synthetic@example.invalid',EmailEncodingKey='UTF-8',LastName='Synthetic',LanguageLocaleKey='en_US',LocaleSidKey='en_US',TimeZoneSidKey='America/Los_Angeles',ProfileId=profile.Id,Username='synthetic.'+UserInfo.getOrganizationId()+'.'+String.valueOf(Crypto.getRandomInteger())+'@example.invalid');
 }
 static List<Boolean> permissions() {
  return new List<Boolean>{FeatureManagement.checkPermission('Synthetic_View'),FeatureManagement.checkPermission('Synthetic_Missing'),Synthetic_Item__c.SObjectType.getDescribe().isAccessible(),Synthetic_Item__c.SObjectType.getDescribe().isCreateable(),Synthetic_Item__c.SObjectType.getDescribe().isUpdateable(),Synthetic_Item__c.SObjectType.getDescribe().isDeletable(),Synthetic_Item__c.Secret__c.getDescribe().isAccessible(),Synthetic_Item__c.Secret__c.getDescribe().isUpdateable()};
 }
 @IsTest static void runningUser() {
  List<Boolean> row=permissions();
  System.assert(false,'PERMISSION_ROW|'+JSON.serialize(row));
 }
 @IsTest static void otherUser() {
  User other=actor();insert other;
  System.runAs(other){List<Boolean> row=permissions();System.assert(false,'PERMISSION_ROW|'+JSON.serialize(row));}
 }
 @IsTest static void directAssignment() {
  User other=actor();insert other; List<Boolean> row=new List<Boolean>();
  System.runAs(other){row.addAll(permissions());}
  PermissionSet grant=[SELECT Id FROM PermissionSet WHERE Name='Synthetic_Access'];
  insert new PermissionSetAssignment(AssigneeId=other.Id,PermissionSetId=grant.Id);
  System.runAs(other){row.addAll(permissions());}
  System.assert(false,'PERMISSION_ROW|'+JSON.serialize(row));
 }
 @IsTest static void groupAssignment() {
  User other=actor();insert other; List<Boolean> row=new List<Boolean>();
  System.runAs(other){row.addAll(permissions());}
  PermissionSetGroup grant=[SELECT Id,Status FROM PermissionSetGroup WHERE DeveloperName='Synthetic_Group'];
  if(grant.Status!='Updated'){Test.calculatePermissionSetGroup(grant.Id);}
  insert new PermissionSetAssignment(AssigneeId=other.Id,PermissionSetGroupId=grant.Id);
  System.runAs(other){row.addAll(permissions());}
  System.assert(false,'PERMISSION_ROW|'+JSON.serialize(row));
 }
}
